import { useMediaQuery, useTheme } from '@mui/material';

type StepperBreakpoint = 'sm' | 'md';

export function useResponsiveStepperOrientation(breakpoint: StepperBreakpoint = 'sm') {
  const theme = useTheme();
  const isCompact = useMediaQuery(theme.breakpoints.down(breakpoint));

  return {
    isCompact,
    orientation: isCompact ? ('vertical' as const) : ('horizontal' as const),
    alternativeLabel: !isCompact,
  };
}
