import React, { useState } from 'react';
import {
  Alert,
  Button,
  Stack,
  Step,
  StepLabel,
  Stepper,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { useResponsiveStepperOrientation } from '../../hooks/useResponsiveStepperOrientation';

export const COMPLIANCE_HUB_ONBOARDING_KEY = 'ci_compliance_hub_onboarding_dismissed';

const ComplianceHubOnboardingGuide: React.FC = () => {
  const { strings } = useReadinessLocale();
  const { orientation, alternativeLabel } = useResponsiveStepperOrientation();
  const [dismissed, setDismissed] = useState(() => {
    if (typeof window === 'undefined') {
      return true;
    }
    return window.localStorage.getItem(COMPLIANCE_HUB_ONBOARDING_KEY) === '1';
  });

  if (dismissed) {
    return null;
  }

  const dismiss = () => {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(COMPLIANCE_HUB_ONBOARDING_KEY, '1');
    }
    setDismissed(true);
  };

  const steps = strings.onboardingSteps;

  return (
    <Alert severity="info" sx={{ mb: 3 }}>
      <Typography variant="subtitle2" fontWeight={700} gutterBottom>
        {strings.onboardingTitle}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {strings.onboardingSubtitle}
      </Typography>
      <Stepper activeStep={-1} orientation={orientation} alternativeLabel={alternativeLabel} sx={{ mb: 2 }}>
        {steps.map((label) => (
          <Step key={label} completed={false}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems="center">
        <Button component={RouterLink} to={DOCUMENT_UPLOAD_PATH} variant="contained" size="small">
          {strings.onboardingUploadBills}
        </Button>
        <Button variant="text" size="small" onClick={dismiss}>
          {strings.onboardingDismiss}
        </Button>
      </Stack>
    </Alert>
  );
};

export default ComplianceHubOnboardingGuide;
